WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, ROUND(SUM(burst_id) / NULLIF(COUNT(CASE WHEN event_type = 'purchase' THEN 1 END), 0), 2) AS burst_id_per_purchase, COUNT_IF(event_type = 'click') AS click_events, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM sessions_web_events GROUP BY DATE_TRUNC('YEAR', event_time);
